struct LoggingProxy<T: Render> { inner: T, calls: Cell<u64> }

impl<T: Render> Render for LoggingProxy<T> {
    fn render(&self) -> String {
        self.calls.set(self.calls.get() + 1);
        self.inner.render()
    }
}

